import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * FreightCalc.calc 的现状锁定测试（characterization test）。
 *
 * 目的不是证明算得对，是把「今天算出来是多少」钉死，改之前先有个红绿灯。
 * 所以下面每个期望值都是「代码现在的输出」，不是「业务应该的输出」。
 * 注释与实现对不上的地方（0.5kg 进位、vip 免续重），单独在用例里标了「注释 vs 实现」。
 *
 * 走的这条真实请求：模板 1032、目的地新疆、weight=3.2、vip=false、cod=false。
 * 其余用例都只动一个变量，把 calc 里的一步单独露出来。
 *
 * 用到的三个数据点（主人确认的事实）：
 *   tpl(1032).first    = 18
 *   tpl(1032).next     = 4
 *   region("新疆").surcharge = 3
 * 全部用例都固定 tplId=1032、province="新疆"，只依赖这三个数，
 * 所以区域表里有没有「新疆」单独一行、还是走西北大区兜底，不影响期望值。
 *
 * 【重要】本机 Bash 不可用，这些期望值是我对着代码手算出来的（推断），不是跑出来的（观察）。
 * 第一次跑起来若有哪条红了，以实际输出为准改期望值 —— 那说明我读错了，不说明代码错了。
 *
 * 【假设】Req 有无参构造，且 tplId/weight/vip/cod/province 可直接赋值
 *         （依据只是 calc 里用的是 r.xxx 字段访问；若实际是 builder 或全参构造，改 req() 这一个方法即可）。
 * 【假设】new FreightCalc() 出来的对象，tpl()/region() 就能拿到真实的模板表和区域表。
 *         若这两个方法背后是查库/查配置，这个测试跑不起来，得换 Subclass and Override Method 挡住它们。
 */
class FreightCalcCharacterizationTest {

    private static final int TPL_ID = 1032;
    private static final String PROVINCE = "新疆";

    // ---------- 第 1 步：首重 ----------

    @Test
    @DisplayName("第1步 首重：1.0kg 不进续重分支，只有首重 + 区域加价")
    void firstWeightOnly_atExactlyOneKg() {
        // weight > 1.0 是严格大于，1.0 本身不触发续重。
        // 18（首重） + 0（续重） + 3（新疆加价） + 0（非 cod）
        assertEquals(21, new FreightCalc().calc(req(1.0, false, false)),
                "1.0kg 应该只收首重加区域加价");
    }

    @Test
    @DisplayName("第2步 续重触发：超过 1.0kg 一点点，也要整整一档")
    void extraWeight_isChargedAsAWholeStep() {
        // extra = (int) Math.ceil(1.01 - 1.0) = 1，unit = 4
        // 18 + 1×4 + 3
        assertEquals(25, new FreightCalc().calc(req(1.01, false, false)),
                "超重 0.01kg 也按一整档收");
    }

    @Test
    @DisplayName("第2步 进位粒度：续重按 1kg 整档，不是文件头注释说的 0.5kg")
    void extraWeight_stepsByOneKilogram_notHalf() {
        // 注释 vs 实现：文件头写「续重按 0.5kg 进位」，代码是 Math.ceil(weight - 1.0)，按 1kg。
        // 这条就是用来分辨两者的：2.0kg 的续重部分正好 1.0kg，
        //   按代码（1kg 档）= 1 档 = 4 元 → 25
        //   若真按 0.5kg 档          = 2 档 = 8 元 → 29
        // 这里钉的是代码的现状 25。若业务口径是 0.5kg，那是另一个 bug，另开单修，别改这条。
        assertEquals(25, new FreightCalc().calc(req(2.0, false, false)),
                "续重 1.0kg 现在只算 1 档");
    }

    // ---------- 主用例：那条真实请求 ----------

    @Test
    @DisplayName("主用例 模板1032 / 新疆 / 3.2kg / 非vip / 非cod")
    void realRequest_tpl1032_xinjiang_3_2kg() {
        // 逐步走：
        //   fee   = 18                                （tpl(1032).first）
        //   extra = (int) Math.ceil(3.2 - 1.0) = 3     （2.2 向上取整到 3）
        //   unit  = 4                                  （非 vip，不减半）
        //   fee  += 3 × 4 = 12                        → 30
        //   fee  += 3                                  （region("新疆").surcharge）→ 33
        //   cod   = false，不加 2
        assertEquals(33, new FreightCalc().calc(req(3.2, false, false)),
                "这条真实请求现在算出来是 33");
    }

    // ---------- 第 3 步：vip ----------

    @Test
    @DisplayName("第3步 vip：续重是半价，不是文件头注释说的免费")
    void vip_halvesTheUnitPrice_doesNotWaiveIt() {
        // 注释 vs 实现：文件头写「vip 免续重」，代码是 unit = unit / 2，半价。
        //   unit = 4 / 2 = 2，extra = 3
        //   18 + 3×2 = 24，+3 = 27
        // 若真「免续重」，应该是 18 + 0 + 3 = 21。现状是 27。
        assertEquals(27, new FreightCalc().calc(req(3.2, true, false)),
                "vip 现在是续重半价，不是免单");
    }

    @Test
    @DisplayName("第3步 vip：不影响首重")
    void vip_doesNotTouchFirstWeight() {
        // vip 的判断在续重分支里面，1.0kg 根本进不去，所以和非 vip 一样是 21。
        assertEquals(21, new FreightCalc().calc(req(1.0, true, false)),
                "vip 不减首重");
    }

    // ---------- 第 4 步：区域加价 ----------

    @Test
    @Disabled("【假设】没有证据：不知道哪个省份能让 region() 返回 null。"
            + "拿到一个真实样例（或确认区域表全覆盖、null 是死分支）后再补期望值。")
    @DisplayName("第4步 区域加价：region() 返回 null 的分支 —— 现状未知，先不猜")
    void unknownRegion_fallsToZeroSurcharge() {
        // else 分支写的是 fee += 0，按字面读等于不加价。
        // 但我拿不出一个真会走到这里的省份，所以不写期望值，免得把猜的数字锁成「现状」。
        // 另外 region(null) 会不会直接抛异常，也没有证据。
    }

    // ---------- 第 5 步：cod ----------

    @Test
    @DisplayName("第5步 cod：在主用例上固定加 2，且这个 2 不来自模板")
    void cod_addsFlatTwo() {
        // 33（主用例） + 2
        assertEquals(35, new FreightCalc().calc(req(3.2, false, true)),
                "cod 现在是写死的 +2");
    }

    // ---------- 工具 ----------

    /** 只留 weight/vip/cod 三个变量，tplId 和 province 全用例固定，保证每条只露一步。 */
    private static Req req(double weight, boolean vip, boolean cod) {
        Req r = new Req();
        r.tplId = TPL_ID;
        r.province = PROVINCE;
        r.weight = weight;
        r.vip = vip;
        r.cod = cod;
        return r;
    }
}

